def extract_artist(event_name):
    """Extract clean artist name from event name for API lookups.
    Strips tour names, featured artists, venue info, date suffixes, etc."""
    import re
    s = event_name.strip()
    if not s: return s

    # Split on common tour/subtitle separators and take the artist part
    for sep in [' - ', ' – ', ' — ', ': ', ' | ']:
        if sep in s:
            s = s.split(sep)[0].strip()
            break

    # Remove parenthetical/bracketed suffixes (tour names, years, etc.)
    s = re.sub(r'\s*\([^)]*\)', '', s)
    s = re.sub(r'\s*\[[^\]]*\]', '', s)

    # Remove "feat.", "ft.", "featuring", "with", "x" collaborator suffixes
    s = re.sub(r'\s+(?:feat\.?|ft\.?|featuring|w/)\s+.*$', '', s, flags=re.IGNORECASE)
    # "Artist with Special Guest ..." or "Artist with ..."
    s = re.sub(r'\s+with\s+(?:special\s+)?(?:guest[s]?\s+)?.*$', '', s, flags=re.IGNORECASE)
    # "Artist & Other" — only strip if after main artist name (3+ words total)
    parts = s.split(' & ')
    if len(parts) >= 2 and len(parts[0].split()) >= 1:
        s = parts[0].strip()
    # "Artist + Other"
    parts = s.split(' + ')
    if len(parts) >= 2:
        s = parts[0].strip()

    # Remove trailing date-like patterns "Nov 15" etc.
    s = re.sub(r'\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d{1,2}.*$', '', s, flags=re.IGNORECASE)

    # Remove "Presented by ..."
    s = re.sub(r'\s+presented\s+by\s+.*$', '', s, flags=re.IGNORECASE)

    return s.strip()

def _normalize_key(s):
    import re as _re
    s = (s or '').lower().strip()
    for sep in [' - ', ': ', ' - ']:
        if sep in s: s = s.split(sep)[0].strip()
    s = _re.sub(r'\\s*\\([^)]*\\)', '', s).strip()
    return s

def _fuzzy_get(db, key):
    if key in db: return db[key]
    for k in db:
        if key in k or k in key: return db[k]
    return None

def get_smart_buy_under(event_name, venue_name, target_margin=0.15):
    artist_key = _normalize_key(event_name)
    venue_key  = _normalize_key(venue_name)
    combo_key  = artist_key + '|||' + venue_key
    av_data = _fuzzy_get(_av_db, combo_key)
    vo_data = _fuzzy_get(_vo_db, venue_key)
    ao_data = _fuzzy_get(_ao_db, artist_key)
    tiers = set()
    for d in [av_data, vo_data, ao_data]:
        if d: tiers.update(d.keys())
    result = {}
    for tier in tiers:
        sources = []
        if av_data and tier in av_data and av_data[tier]['count'] >= 3:
            sources.append((av_data[tier], 0.50))
        if vo_data and tier in vo_data and vo_data[tier]['count'] >= 5:
            sources.append((vo_data[tier], 0.30))
        if ao_data and tier in ao_data and ao_data[tier]['count'] >= 3:
            sources.append((ao_data[tier], 0.20))
        if not sources: continue
        total_w = sum(w for _, w in sources)
        blended_sell   = sum(d['avg_sell']   * (w/total_w) for d, w in sources)
        blended_cost   = sum(d['avg_cost']   * (w/total_w) for d, w in sources)
        blended_margin = sum(d['avg_margin'] * (w/total_w) for d, w in sources)
        buy_under = round(blended_sell / (1 + target_margin), 2)
        result[tier] = {
            'avg_sell':   round(blended_sell, 2),
            'avg_cost':   round(blended_cost, 2),
            'avg_margin': round(blended_margin, 1),
            'buy_under':  buy_under,
            'count':      sum(d['count'] for d, _ in sources),
            'sources':    len(sources),
        }
    return result if result else None

# ── Expected dollar profit lookup ─────────────────────────────────────────────
# Loads _artist_events from concert + sports analyzers and indexes by artist,
# so we can pull (avg_profit_per_event, avg_tickets_per_event) on demand.
# Cached in-process — same lazy pattern as the section data load.
_dollar_data_loaded = False
_artist_event_stats = {}  # artist_key -> {avg_profit, avg_tickets, count, avg_margin}


def _load_dollar_data():
    global _dollar_data_loaded, _artist_event_stats
    if _dollar_data_loaded: return
    import ast as _ast
    here = os.path.dirname(os.path.abspath(__file__))
    raw = {}
    for fname in ("concert_historical.py", "sports_historical.py"):
        path = os.path.join(here, fname)
        if not os.path.exists(path): continue
        try:
            with open(path, encoding="utf-8") as f:
                tree = _ast.parse(f.read())
            for node in tree.body:
                if not isinstance(node, _ast.Assign) or len(node.targets) != 1: continue
                t = node.targets[0]
                if isinstance(t, _ast.Name) and t.id == "_artist_events":
                    for a, evs in _ast.literal_eval(node.value).items():
                        raw.setdefault(a, []).extend(evs)
        except Exception as e:
            print(f"[dollar-data] failed parsing {fname}: {e}")
    for a, evs in raw.items():
        if not evs: continue
        profits = [e.get("profit") or 0 for e in evs]
        tickets = [e.get("tickets") or 0 for e in evs]
        margins = [e.get("margin") or 0 for e in evs]
        prof_count = sum(1 for e in evs if e.get("profitable"))
        _artist_event_stats[a] = {
            "avg_profit":  round(sum(profits) / len(profits), 2),
            "avg_tickets": round(sum(tickets) / len(tickets), 1),
            "avg_margin":  round(sum(margins) / len(margins), 1),
            "count":       len(evs),
            "profitable_pct": round(prof_count / len(evs) * 100, 0),
        }
    _dollar_data_loaded = True


def get_expected_profit(event_name):
    """Returns {avg_profit, avg_tickets, count, profitable_pct, avg_margin}
    for this artist (from our past sales) or None if no history."""
    _load_dollar_data()
    key = _normalize_key(event_name)
    return _fuzzy_get(_artist_event_stats, key)


# ── Auto-detected loser list (data-driven) ───────────────────────────────────
# Replaces the hardcoded "Aerosmith / Panic! / etc." pattern list.
# Auto-builds from _artist_events: artists with avg margin < -10% across
# 5+ events. Refreshes whenever _load_dollar_data() runs.
_auto_loser_artists = None


def get_auto_loser_artists():
    """Returns set of artist keys with consistent negative margin (>=5 events,
    avg margin < -10%). Used to penalize bad picks beyond the hardcoded list."""
    global _auto_loser_artists
    if _auto_loser_artists is not None: return _auto_loser_artists
    _load_dollar_data()
    losers = set()
    for a, stats in _artist_event_stats.items():
        if stats["count"] >= 5 and stats["avg_margin"] < -10:
            losers.add(a)
    _auto_loser_artists = losers
    return losers


def auto_loser_score(event_name):
    """Returns -10 if event_name matches an auto-detected loser, 0 otherwise."""
    losers = get_auto_loser_artists()
    if not losers: return 0
    key = _normalize_key(event_name)
    if key in losers: return -10
    # Substring match for partial names
    for loser in losers:
        if loser in key or key in loser:
            return -10
    return 0


# ── Cross-market arbitrage ────────────────────────────────────────────────────
# For an event we're considering buying, find other upcoming dates by the same
# artist in different cities and compare predicted margins. Helps decide which
# city to focus on for the same artist.
def get_cross_market_options(event_name, current_venue, current_date):
    """Returns list of {venue, city, date, predicted_margin, hist_events} for
    other upcoming dates by this artist at different venues. Reads from the
    Flare cache (which has all upcoming events with venue+date+city)."""
    artist = _normalize_key(extract_artist(event_name) or event_name)
    if not artist:
        return []
    flare_cache = os.path.join(
        os.path.dirname(os.path.abspath(__file__)),
        "..", "..", "Ticket-tools-gct", "state", "flare-events-cache.json"
    )
    flare_cache = os.path.normpath(flare_cache)
    if not os.path.exists(flare_cache):
        return []
    try:
        with open(flare_cache, encoding="utf-8") as f:
            cache = json.load(f)
    except Exception:
        return []
    cur_venue_key = _normalize_key(current_venue)
    other_dates = []
    seen_venues = {cur_venue_key}
    for e in cache.get("events", []):
        ename = (e.get("event_name") or "").lower().strip()
        # Match: this event's normalized artist appears in the flare event name
        ename_artist = _normalize_key(extract_artist(ename) or ename)
        if artist != ename_artist and not (artist in ename or ename_artist in artist):
            continue
        venue = (e.get("venue_name") or "").strip()
        vk = _normalize_key(venue)
        if vk == cur_venue_key or vk in seen_venues:
            continue
        seen_venues.add(vk)
        # Look up our historical margin at this artist+venue
        av_key = artist + "|||" + vk
        av_data = _fuzzy_get(_av_db, av_key)
        if not av_data:
            continue  # no history → can't compare
        # Average margin across all tiers we have data for
        margins = [d.get("avg_margin", 0) for d in av_data.values() if d.get("count", 0) >= 3]
        if not margins:
            continue
        avg_margin = sum(margins) / len(margins)
        total_tickets = sum(d.get("count", 0) for d in av_data.values())
        other_dates.append({
            "venue": venue,
            "city": e.get("venue_city") or "",
            "date": e.get("event_date") or "",
            "predicted_margin": round(avg_margin, 1),
            "history_tickets": total_tickets,
            "spotify_popularity": e.get("spotify_popularity"),
        })
    other_dates.sort(key=lambda x: -x["predicted_margin"])
    return other_dates[:5]


# ── Per-section resale prediction ─────────────────────────────────────────────
# Section-level data lives in concert_historical.py / sports_historical.py
# (as _av_sec and _ao_sec). presale_analyzer.py only has tier-level data, so
# we lazy-load section data from those files on first use and cache in-process.
_section_data_loaded = False
_av_sec_cache = {}
_ao_sec_cache = {}


def _load_section_data():
    """Parse _av_sec and _ao_sec from the historical analyzers. Best-effort —
    if files are missing or unparseable, we fall back to tier-level data."""
    global _section_data_loaded, _av_sec_cache, _ao_sec_cache
    if _section_data_loaded: return
    import ast as _ast
    here = os.path.dirname(os.path.abspath(__file__))
    for fname in ("concert_historical.py", "sports_historical.py"):
        path = os.path.join(here, fname)
        if not os.path.exists(path): continue
        try:
            with open(path, encoding="utf-8") as f:
                tree = _ast.parse(f.read())
            for node in tree.body:
                if not isinstance(node, _ast.Assign) or len(node.targets) != 1: continue
                t = node.targets[0]
                if not isinstance(t, _ast.Name): continue
                if t.id == "_av_sec":
                    _av_sec_cache.update(_ast.literal_eval(node.value))
                elif t.id == "_ao_sec":
                    _ao_sec_cache.update(_ast.literal_eval(node.value))
        except Exception as e:
            print(f"[section-data] failed to parse {fname}: {e}")
    _section_data_loaded = True


def predict_via_formula(event_name, venue_name):
    """Formula-based tier-level prediction for events with no exact history.

    Combines two independently-derived signals:
      1. Venue's typical face per tier (from _vo_db) — any artist who's played
         this venue. Tells us the baseline price for each tier.
      2. Artist's typical resale lift (from _history_db) — avg_sell / avg_cost.
         Tells us how much premium THIS artist tends to command above face.

    Predicted resale = venue_face × artist_lift

    Each entry includes the formula breakdown so the user can see the math.
    Returns [] if we lack the inputs to compute a meaningful prediction.
    """
    artist_key = _normalize_key(event_name)
    venue_key  = _normalize_key(venue_name)

    # Step 1: venue's tier-level face history (any artist)
    venue_tiers = _fuzzy_get(_vo_db, venue_key)
    if not venue_tiers:
        return []

    # Step 2: artist's overall lift multiplier (resale / cost) from _history_db
    hist = lookup_artist_history(event_name, _history_db)
    if not hist:
        return []
    artist_sell = hist.get("avg_sell_price") or 0
    artist_cost = hist.get("avg_cost_price") or 0
    if artist_cost <= 0:
        return []
    artist_lift = artist_sell / artist_cost  # e.g., 2.6 for YUNGBLUD

    out = []
    for tier, stats in venue_tiers.items():
        venue_face = stats.get("avg_cost") or 0
        venue_count = stats.get("count", 0)
        if venue_face <= 0 or venue_count < 5:
            continue  # need enough venue history at this tier
        predicted_resale = round(venue_face * artist_lift, 2)
        predicted_margin = round((predicted_resale - venue_face) / venue_face * 100, 1)
        # Confidence: combo of venue sample size + artist sample size
        artist_events = hist.get("events", 0)
        if venue_count >= 30 and artist_events >= 10: conf = "medium"
        elif venue_count >= 10 and artist_events >= 5: conf = "low"
        else:                                          conf = "low"
        out.append({
            "tier": tier,
            "predicted_face": round(venue_face, 2),
            "predicted_resale": predicted_resale,
            "predicted_margin": predicted_margin,
            "venue_count": venue_count,
            "artist_events": artist_events,
            "artist_lift": round(artist_lift, 2),
            "confidence": conf,
            "formula": f"${venue_face:.0f} (venue typical) × {artist_lift:.2f}x (artist lift, {artist_events}ev) = ${predicted_resale:.0f}",
        })
    out.sort(key=lambda x: -x["predicted_margin"])
    return out


def get_section_predictions(event_name, venue_name, max_sections=12):
    """Returns list of {section, tier, predicted_sell, predicted_cost,
    predicted_margin, count, confidence}, sorted by margin desc.

    Uses _av_sec (artist+venue+section) as primary source, falls back to
    _ao_sec (artist+section, ignoring venue) if no artist+venue match.
    Sections need >=3 historical sales to be included — avoids noise.
    """
    _load_section_data()
    artist_key = _normalize_key(event_name)
    venue_key  = _normalize_key(venue_name)
    av_key     = artist_key + '|||' + venue_key

    # Only use artist+venue data. The artist-only fallback was producing
    # misleading results: section names (BALC1, etc.) mean different things at
    # different venues, so mixing face from cheap club venues with resale from
    # expensive arenas gave nonsense margins like +844%. Better to show
    # nothing than to show wrong numbers.
    primary = _fuzzy_get(_av_sec_cache, av_key)
    if not primary:
        return []

    out = []
    for tier, sec_dict in primary.items():
        for section, stats in sec_dict.items():
            if stats.get("count", 0) < 3: continue
            sell = stats.get("avg_sell") or 0
            cost = stats.get("avg_cost") or 0
            # Skip entries with $0 face (comp tickets / data errors) — they
            # produce meaningless margin signals.
            if cost <= 1: continue
            margin = stats.get("avg_margin") or 0
            cnt = stats.get("count", 0)
            if cnt >= 10:   conf = "high"
            elif cnt >= 5:  conf = "medium"
            else:           conf = "low"
            out.append({
                "section": section,
                "tier": display_tier(section, tier),
                "predicted_sell": round(sell, 2),
                "predicted_cost": round(cost, 2),
                "predicted_margin": round(margin, 1),
                "count": cnt,
                "confidence": conf,
                "source": "artist+venue",
            })

    out.sort(key=lambda s: -s["predicted_margin"])
    return out[:max_sections]


