def check_venue_upgrade(event_name, current_cap):
    import re as _re
    def normalize(s):
        s = (s or '').lower().strip()
        for sep in [' - ', ': ', ' – ']:
            if sep in s: s = s.split(sep)[0].strip()
        s = _re.sub(r'\s*\([^)]*\)', '', s).strip()
        return s
    key = normalize(event_name)
    hist_cap = None
    if key in _artist_hist_cap:
        hist_cap = _artist_hist_cap[key]
    else:
        for k in _artist_hist_cap:
            if k in key or key in k:
                hist_cap = _artist_hist_cap[k]
                break
    if not hist_cap or not current_cap or current_cap == 0:
        return None, None
    ratio = current_cap / hist_cap
    if ratio >= 3:
        return "major_upgrade", round(ratio, 1)
    elif ratio >= 2:
        return "upgrade", round(ratio, 1)
    elif ratio <= 0.4:
        return "smaller", round(ratio, 1)
    return None, None

