def lookup_artist_history(event_name, history_db):
    """Fuzzy match event name against history database."""
    if not history_db: return None
    import re

    def normalize(s):
        s = s.lower()
        # Strip tour suffixes
        for sep in [' - ', ': ', ' – ']:
            if sep in s:
                s = s.split(sep)[0].strip()
        s = re.sub(r'\s*\([^)]*\)', '', s)
        s = re.sub(r'[^\w\s]', '', s).strip()
        return s

    key = normalize(event_name)

    # Exact match first
    if key in history_db:
        return history_db[key]

    # Partial match — event name contains artist name or vice versa
    for db_key, data in history_db.items():
        if db_key in key or key in db_key:
            return data

    return None

def history_score(hist):
    """Score based on personal sales history. This is the strongest signal."""
    if not hist: return 0, None

    margin = hist['avg_margin']
    events = hist['events']
    profitable_pct = hist['profitable_pct']

    # Confidence multiplier — single events are nearly meaningless
    if events >= 20:    conf_mult = 1.0
    elif events >= 10:  conf_mult = 0.85
    elif events >= 5:   conf_mult = 0.65
    elif events >= 3:   conf_mult = 0.45
    elif events >= 2:   conf_mult = 0.25
    else:               conf_mult = 0.10  # 1 event = almost no signal

    # Base score from avg margin
    if margin >= 100:    base = 60
    elif margin >= 75:   base = 52
    elif margin >= 50:   base = 44
    elif margin >= 30:   base = 35
    elif margin >= 15:   base = 25
    elif margin >= 0:    base = 12
    elif margin >= -20:  base = -8
    elif margin >= -50:  base = -20
    else:                base = -35

    return round(base * conf_mult), margin

# ── Progress tracking ─────────────────────────────────────────────────────────
_progress = {"status": "idle", "current": 0, "total": 0, "artist": "", "phase": ""}

def set_progress(current, total, artist="", phase=""):
    _progress["status"] = "running"
    _progress["current"] = current
    _progress["total"] = total
    _progress["artist"] = artist
    _progress["phase"] = phase

def done_progress():
    _progress["status"] = "done"
