def get_metro(city):
    """Map a city to its metro area for scoring purposes."""
    c = (city or "").lower().strip()
    return METRO_MAP.get(c, c)

def city_market_score(city):
    """Boost for strong ticket markets — use metro area mapping."""
    metro = get_metro(city)
    if metro in CITY_TIER1: return 8
    if metro in CITY_TIER2: return 4
    return 0

