def detect_league(event_name):
    """Return league code or None. Used to pick DOW scoring profile for sports."""
    n = (event_name or "").lower()
    # NHL/NBA before NFL because some team names overlap (giants, rangers, kings)
    for lg in ("NHL", "NBA", "MLB", "NFL", "MLS", "NCAA"):
        for hint in _LEAGUE_HINTS[lg]:
            if hint in n:
                return lg
    return None


# Day-of-week weights per league, derived from actual margin data in
# _artist_events (see backtest_presale.py). Concerts treat all days roughly
# equal; sports vary wildly by league.
#
# Index 0=Mon .. 6=Sun. Range tuned to fit the existing 0-8 DOW pts budget.
_DOW_WEIGHTS = {
    "concert": [3, 4, 2, 3, 5, 6, 5],          # Sat best, narrow range
    "MLB":     [-3, -5, -4, -1, 5, 8, 4],       # Sat 41% margin, Tue -11%
    "NHL":     [-5, -5, -5, -2, 2, 8, 1],       # Sat dominant, weekdays brutal
    "NBA":     [-1, -4, 0, 0, 3, 7, 7],         # Sat/Sun strong, Tue avoid
    "NFL":     [6, -6, -3, 5, 0, 2, 8],         # Mon Night Football +; Sun best
    "NCAA":    [-6, -4, 3, 1, 6, 10, 7],        # Sat is everything (cfb)
    "MLS":     [-2, -8, 2, -3, 7, 1, 7],        # small sample but consistent
    "sports":  [-3, -5, -3, 0, 4, 7, 5],         # generic sports fallback
}


def day_of_week_score(event_date_str, event_name="", source="concert"):
    """Returns DOW score using league-specific weights when sports.

    source: "concert" or "sports" — selects baseline profile.
    For sports, we try to detect the specific league for a sharper weight.
    """
    if not event_date_str: return 0
    try:
        dt = datetime.strptime(str(event_date_str)[:10], "%Y-%m-%d")
        dow = dt.weekday()
        if source == "sports":
            lg = detect_league(event_name)
            weights = _DOW_WEIGHTS.get(lg) or _DOW_WEIGHTS["sports"]
        else:
            weights = _DOW_WEIGHTS["concert"]
        return weights[dow]
    except Exception:
        return 0


# ── Venue type score ──────────────────────────────────────────────────────────
# Backtest of 13K events: theater 66% profitable / 18.8% median margin (highest),
# amphitheater 53% / 6% (worst). Arenas oversupplied, stadiums OK, clubs scarce.
def venue_type_score(venue_name):
    n = (venue_name or "").lower()
    if any(w in n for w in ("theatre", "theater", "hall", "auditorium", "palace", "rodgers")):
        return 8
    if any(w in n for w in ("club", "lounge", "house of blues")):
        return 6
    if any(w in n for w in ("stadium", "field", "park", "coliseum")):
        return 3
    if any(w in n for w in ("amphitheater", "amphitheatre", "pavilion")):
        return -3
    if any(w in n for w in ("arena", "center", "centre", "garden", "forum", "fieldhouse")):
        return 0
    return 0


# ── Pattern bonuses (event-name keyword scan) ─────────────────────────────────
# Each tuple: (label, keyword list, points). Values calibrated from backtest:
# Taylor Swift 92% profitable, rivalry games 77%, Ohio State 75%, etc.
_PATTERN_BONUSES = [
    ("Taylor Swift",   ("taylor swift",),                                +15),
    ("Eras Tour",      ("eras tour",),                                   +12),
    ("Rivalry game",   ("yankees vs. red sox", "red sox vs. yankees",
                        "cubs vs. dodgers", "yankees vs. mets",
                        "ohio state vs. michigan", "michigan vs. ohio state",
                        "alabama vs. auburn", "auburn vs. alabama",
                        "duke vs. unc", "unc vs. duke",
                        "ucla vs. usc", "usc vs. ucla",
                        "michigan vs. michigan state",
                        "michigan state vs. michigan"),                  +15),
    ("Ohio State CFB", ("ohio state buckeyes", "buckeyes vs."),          +8),
    ("Michigan CFB",   ("michigan wolverines",),                         +6),
    ("Hamilton",       ("hamilton",),                                    +10),
    ("Playoff/Finals", ("playoff", "world series", "stanley cup",
                        "nba finals"),                                   +8),
    ("Championship",   ("championship",),                                +5),
    ("Bowl game",      (" bowl ", " bowl,", " bowl$"),                   +4),
    ("Savannah Bananas",("savannah bananas",),                           +10),
    ("Romeo/Prince",   ("romeo santos", "prince royce"),                 +8),
    ("Mana",           ("mana ",),                                       +6),
    # Past-peak / known-losers (negative bonuses)
    ("Past-peak",      ("aerosmith", "panic! at the disco",
                        "chance the rapper", "lewis black",
                        "1776 - the musical", "1776 the musical",
                        "nct dream"),                                    -10),
]


def pattern_bonus_score(event_name):
    """Sum of all matching pattern bonuses for this event name.

    Cap at +20 / -15 to keep one mega-match from dominating the score.
    """
    n = (event_name or "").lower()
    total = 0
    matches = []
    for label, kws, pts in _PATTERN_BONUSES:
        for kw in kws:
            if kw.endswith("$"):
                if n.endswith(kw[:-1]):
                    total += pts; matches.append(label); break
            elif kw in n:
                total += pts; matches.append(label); break
    return max(-15, min(20, total)), matches


# ── Sports month penalty ──────────────────────────────────────────────────────
# Backtest: April -7.8% median, May -2%, Aug +2.8%, Nov +2.9% — historically soft
# months for sports. Concerts don't show the same dip.
def month_penalty_sports(event_date_str):
    try:
        dt = datetime.strptime(str(event_date_str)[:10], "%Y-%m-%d")
        m = dt.month
        if m == 4: return -8       # April: worst month for sports
        if m == 5: return -5       # May: regular season doldrums
        if m == 8: return -4       # Aug: NFL preseason / MLB lull
        if m == 11: return -3      # Nov: NFL late season variability
        if m in (10, 3, 1): return +3   # NFL kickoff streak / March Madness / NFL playoffs
    except Exception:
        pass
    return 0


# ── Venue blacklist (with DOW context) ───────────────────────────────────────
# Derived from backtest: venues with sustained negative margin across the full
# history. The key insight (Fiserv Forum) is that some bad venues are only bad
# on certain days — Fiserv Sat/Fri actually break even. So blacklists are
# (venue, allowed_dow_set) — penalty applied UNLESS the DOW is in the safe set.
_VENUE_BLACKLIST = {
    "fiserv forum":     ({4, 5}, -10),               # OK Fri/Sat, brutal otherwise
    "citi field":       (set(), -8),
    "upmc events center": (set(), -15),
    "galen center":     (set(), -10),
    "the watsco center at um": (set(), -12),
    "clearview arena":  (set(), -12),
    "desert diamond arena": (set(), -8),
}


def venue_blacklist_score(venue_name, event_date_str):
    """Penalize known loss-generator venues. Some have DOW exceptions."""
    v = (venue_name or "").lower().strip()
    if v not in _VENUE_BLACKLIST:
        return 0
    allowed_dows, penalty = _VENUE_BLACKLIST[v]
    if not allowed_dows:
        return penalty  # blanket avoid
    try:
        dt = datetime.strptime(str(event_date_str)[:10], "%Y-%m-%d")
        if dt.weekday() in allowed_dows:
            return 0  # DOW exception — venue is fine on this day
    except Exception:
        pass
    return penalty


